class Solution {
public:
    int fourSumCount(vector<int>& nums1, vector<int>& nums2, vector<int>& nums3, vector<int>& nums4) {
        unordered_map<int, int> abSums;
        for (int a : nums1) {
            for (int b : nums2) {
                abSums[a + b]++;
            }
        }
        int count = 0;
        for (int c : nums3) {
            for (int d : nums4) {
                auto it = abSums.find(-(c + d));
                if (it != abSums.end()) count += it->second;
            }
        }
        return count;
    }
};

class Solution {
    public int fourSumCount(int[] nums1, int[] nums2, int[] nums3, int[] nums4) {
        Map<Integer, Integer> abSums = new HashMap<>();
        for (int a : nums1) {
            for (int b : nums2) {
                abSums.put(a + b, abSums.getOrDefault(a + b, 0) + 1);
            }
        }
        int count = 0;
        for (int c : nums3) {
            for (int d : nums4) {
                count += abSums.getOrDefault(-(c + d), 0);
            }
        }
        return count;
    }
}

